import csv, re, datetime
from collections import Counter, defaultdict
rows=list(csv.DictReader(open('expenses.csv')))
def parse_date(s):
    s=s.strip()
    for fmt in ('%m/%d/%Y','%d %b %Y','%Y-%m-%d'):
        try: return datetime.datetime.strptime(s,fmt).date()
        except ValueError: pass
def parse_amt(s):
    return float(re.sub(r'[^0-9.\-]','',s.strip()))
seen=set(); uniq=[]
for r in rows:
    k=tuple(r.values())
    if k not in seen: seen.add(k); uniq.append(r)
for r in uniq:
    r['_date']=parse_date(r['date']); r['_amt']=parse_amt(r['amount']); r['_cat']=r['category'].strip().lower(); r['_status']=r['status'].strip().lower()
ok=sorted([r for r in uniq if r['_date'].year==2026 and r['_date'].month==10 and r['_status']=='ok'], key=lambda r:(r['_date'],int(r['id'])))
for r in ok:
    print(f"| {r['_date'].strftime('%b %-d')} | {r['id']} | {r['_cat'].title()} | ${r['_amt']:,.2f} |")
byday=defaultdict(float)
for r in ok: byday[r['_date']]+=r['_amt']
print('\nDAILY')
for d in sorted(byday): print(d.strftime('%b %-d'),f'{byday[d]:.2f}')
print('\navg', round(sum(r['_amt'] for r in ok)/len(ok),2))
print('min',min(r['_amt'] for r in ok),'max',max(r['_amt'] for r in ok))
PY", "description": "Produce sorted October transaction detail"}

